include <iostream>
include <fstream>
include <string>
include <vector>
include <regex>
include <filesystem>
include <thread>
include <mutex>
include <atomic>
include <algorithm>

std::mutex outputMutex;
std::atomic<int> downloaded(0);
std::atomic<int> skipped(0);

// Extract code blocks from HTML before removing tags
std::string extractCodeBlocks(const std::string& html) {
    std::string result;
    std::regex codeRegex(R"(<pre[^>]>.?</pre>|<code[^>]>.?</code>)", 
                         std::regex::icase | std::regex::ECMAScript);

    auto begin = std::sregex_iterator(html.begin(), html.end(), codeRegex);
    auto end = std::sregex_iterator();

    for (auto it = begin; it != end; ++it) {
        std::string code = it>str();
        // Remove HTML tags from code block
        code = std::regex_replace(code, std::regex("<[^>]>"), "");
        // Decode HTML entities
        code = std::regex_replace(code, std::regex("&lt;"), "<");
        code = std::regex_replace(code, std::regex("&gt;"), ">");
        code = std::regex_replace(code, std::regex("&amp;"), "&");
        code = std::regex_replace(code, std::regex("&quot;"), "\"");
        code = std::regex_replace(code, std::regex("&39;"), "'");
        result += "\n\n" + code + "\n\n";
    }

    return result;
}

// Fast download with code extraction
std::string downloadAndExtractContent(const std::string& url) {
    std::string command = "curl s L '" + url + "'";

    std::string html;
    FILE pipe = popen(command.c_str(), "r");
    if (!pipe) return "";

    char buffer[8192];
    while (fgets(buffer, sizeof(buffer), pipe) != nullptr) {
        html += buffer;
    }
    pclose(pipe);

    if (html.empty()) return "";

    // Extract code blocks FIRST
    std::string codeBlocks = extractCodeBlocks(html);

    // Now extract text content
    std::string text = html;
    text = std::regex_replace(text, std::regex("<script[^>]>.?</script>", std::regex::icase), "");
    text = std::regex_replace(text, std::regex("<style[^>]>.?</style>", std::regex::icase), "");
    text = std::regex_replace(text, std::regex("<[^>]>"), " ");
    text = std::regex_replace(text, std::regex("&nbsp;"), " ");
    text = std::regex_replace(text, std::regex("&lt;"), "<");
    text = std::regex_replace(text, std::regex("&gt;"), ">");
    text = std::regex_replace(text, std::regex("&amp;"), "&");
    text = std::regex_replace(text, std::regex("&quot;"), "\"");
    text = std::regex_replace(text, std::regex("\\s+"), " ");

    // Combine text and code blocks
    return text + "\n\n=== CODE EXAMPLES ===\n" + codeBlocks;
}

// Fast URL extraction
std::vector<std::string> extractUrls(const std::string& filename) {
    std::vector<std::string> urls;
    std::ifstream file(filename);
    if (!file.is_open()) return urls;

    std::string content((std::istreambuf_iterator<char>(file)),
                        std::istreambuf_iterator<char>());

    std::regex urlRegex(R"()");
    auto urls_begin = std::sregex_iterator(content.begin(), content.end(), urlRegex);
    auto urls_end = std::sregex_iterator();

    for (std::sregex_iterator i = urls_begin; i != urls_end; ++i) {
        urls.push_back(i>str());
    }

    return urls;
}

// Fast C++ relevance check with code examples
bool isCppRelevant(const std::string& content) {
    std::string lower = content;
    std::transform(lower.begin(), lower.end(), lower.begin(), 
                  [](unsigned char c){ return std::tolower(c); });

    // Strong C++ indicators
    int cpp_score = 0;

    if (lower.find("c++") != std::string::npos) cpp_score += 10;
    if (lower.find("cpp") != std::string::npos) cpp_score += 5;
    if (lower.find("include") != std::string::npos) cpp_score += 10;
    if (lower.find("std::") != std::string::npos) cpp_score += 8;
    if (lower.find("class ") != std::string::npos) cpp_score += 3;
    if (lower.find("template<") != std::string::npos) cpp_score += 8;
    if (lower.find("namespace") != std::string::npos) cpp_score += 5;

    // Check for code examples section
    if (lower.find("=== code examples ===") != std::string::npos) cpp_score += 5;

    // Heavy Python/JS penalties
    int other_score = 0;
    if (lower.find("import python") != std::string::npos) other_score += 5;
    if (lower.find("def ") != std::string::npos) other_score += 3;
    if (lower.find("require(") != std::string::npos) other_score += 3;
    if (lower.find("npm install") != std::string::npos) other_score += 5;
    if (lower.find("const ") != std::string::npos) other_score += 2;
    if (lower.find("function(") != std::string::npos) other_score += 2;

    // If has C++ code or generic API docs, keep it
    return (cpp_score > 0) || (other_score < 8 && lower.find("api") != std::string::npos);
}

// Clean filename
std::string urlToFilename(const std::string& url) {
    std::string filename = url;
    size_t pos = filename.find("://");
    if (pos != std::string::npos) {
        filename = filename.substr(pos + 3);
    }

    std::replace(filename.begin(), filename.end(), '/', '_');
    std::replace(filename.begin(), filename.end(), '?', '_');
    std::replace(filename.begin(), filename.end(), '=', '_');
    std::replace(filename.begin(), filename.end(), '&', '_');
    std::replace(filename.begin(), filename.end(), '', '_');

    return filename + ".txt";
}

// Worker thread
void processUrls(const std::vector<std::string>& urls, size_t start, size_t end, 
                 const std::string& outputDir, size_t totalUrls) {
    for (size_t i = start; i < end && i < urls.size(); i++) {
        const std::string& url = urls[i];

        {
            std::lock_guard<std::mutex> lock(outputMutex);
            std::cout << "[" << (i + 1) << "/" << totalUrls << "] " << url << std::flush;
        }

        std::string content = downloadAndExtractContent(url);

        if (content.empty() || content.length() < 100) {
            {
                std::lock_guard<std::mutex> lock(outputMutex);
                std::cout << " ⚠ SKIP\n";
            }
            skipped++;
            continue;
        }

        if (!isCppRelevant(content)) {
            {
                std::lock_guard<std::mutex> lock(outputMutex);
                std::cout << " ⊘ NOT C++\n";
            }
            skipped++;
            continue;
        }

        std::string filename = outputDir + "/" + urlToFilename(url);
        std::ofstream outFile(filename);
        if (outFile.is_open()) {
            outFile << content;
            outFile.close();
            {
                std::lock_guard<std::mutex> lock(outputMutex);
                std::cout << " ✓ OK\n";
            }
            downloaded++;
        } else {
            skipped++;
        }
    }
}

int main() {
    const std::string inputFile = "attached_assets/stripedocs.txt";
    const std::string outputDir = "stripe_docs";

    std::filesystem::create_directories(outputDir);

    std::cout << "🚀 C++ CODE EXTRACTOR  Reading URLs...\n";
    std::vector<std::string> urls = extractUrls(inputFile);

    if (urls.empty()) {
        std::cerr << "No URLs found!\n";
        return 1;
    }

    std::cout << "Found " << urls.size() << " URLs\n";
    std::cout << "Extracting text + CODE EXAMPLES with " 
              << std::thread::hardware_concurrency() << " threads...\n\n";

    // Parallel processing
    unsigned int numThreads = std::thread::hardware_concurrency();
    if (numThreads == 0) numThreads = 4;

    std::vector<std::thread> threads;
    size_t urlsPerThread = (urls.size() + numThreads  1) / numThreads;

    for (unsigned int t = 0; t < numThreads; t++) {
        size_t start = t  urlsPerThread;
        size_t end = start + urlsPerThread;

        if (start < urls.size()) {
            threads.emplace_back(processUrls, std::ref(urls), start, end, 
                               std::ref(outputDir), urls.size());
        }
    }

    for (auto& thread : threads) {
        thread.join();
    }

    std::cout << "\n========================================\n";
    std::cout << "✅ COMPLETE!\n";
    std::cout << "Downloaded: " << downloaded << " files (with CODE)\n";
    std::cout << "Skipped: " << skipped << " files\n";
    std::cout << "Output: " << outputDir << "/\n";

    return 0;
}

