    result = std::regex_replace(result, std::regex("&gt;", std::regex::ECMAScript), ">");
    result = std::regex_replace(result, std::regex("&amp;", std::regex::ECMAScript), "&");
    result = std::regex_replace(result, std::regex("&quot;", std::regex::ECMAScript), "\"");
    result = std::regex_replace(result, std::regex("&#39;", std::regex::ECMAScript), "'");
    result = std::regex_replace(result, std::regex("&apos;", std::regex::ECMAScript), "'");
